"""Palindrome detection utilities."""

import re


def normalize(text):
    """Lowercase text and keep only alphanumeric characters."""
    return re.sub(r"[^0-9a-z]", "", text.lower())


def is_palindrome(text, min_length=1):
    """Return True if text is a palindrome of at least min_length characters."""
    cleaned = normalize(text)
    return len(cleaned) >= min_length and cleaned == cleaned[::-1]


def find_word_palindromes(text, min_length=2):
    """Return unique palindromic words found in text (case-insensitive)."""
    words = re.findall(r"[A-Za-z0-9']+", text)
    seen = []
    for word in words:
        if is_palindrome(word, min_length):
            key = word.lower()
            if key not in seen:
                seen.append(key)
    return seen


def find_sentence_palindromes(text, min_length=3):
    """Return sentences in text that are palindromes when normalized."""
    sentences = re.split(r"(?<=[.!?])\s+", text)
    results = []
    for sentence in sentences:
        stripped = sentence.strip()
        if stripped and is_palindrome(stripped, min_length):
            results.append(stripped)
    return results
